/* N7_APPROVED_CHARACTER_V1: original artwork, only UI behavior; isolated from NABOU */
(()=>{'use strict';
if(window.__N7_APPROVED_CHARACTER_V1)return;
window.__N7_APPROVED_CHARACTER_V1=true;
const art={base:'',eyes:''};
const N7_PLACEMENT_VERSION='conversation-status-v2';
const N7_MOTION_VERSION='approved-sideways-v2-2026-11-05';
const motionSource='data:video/mp4;base64,';
const state={motion:null,kind:'idle',previous:new Map(),latest:new Map(),mounted:new Set(),image:null,eyes:null,winkAt:-1};
const label={listen:'Ακούει',idle:'Έτοιμος',think:'Σκέφτεται',work:'Εργάζεται',done:'Ολοκληρώθηκε',error:'Σφάλμα'};
function bytes(s){const raw=atob(s);return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function loadArt(){try{
  const pair=await Promise.all([createImageBitmap(new Blob([bytes(art.base)],{type:'image/webp'})),createImageBitmap(new Blob([bytes(art.eyes)],{type:'image/webp'}))]);
  state.image=pair[0];state.eyes=pair[1];state.mounted.forEach(x=>x.style.visibility='visible');
  const motion=document.createElement('video');
  motion.muted=true;motion.defaultMuted=true;motion.loop=true;motion.autoplay=true;motion.playsInline=true;motion.preload='auto';
  motion.setAttribute('muted','');motion.setAttribute('playsinline','');
  state.motion=motion;
  const preference=window.matchMedia('(prefers-reduced-motion: reduce)');
  function playback(){if(document.hidden||preference.matches){motion.pause();if(preference.matches&&motion.readyState>=1)motion.currentTime=0;}else{motion.play().catch(()=>{});}}
  motion.addEventListener('loadeddata',playback,{once:true});
  preference.addEventListener('change',playback);
  document.addEventListener('visibilitychange',playback);
  motion.src=motionSource;
  motion.load();
}catch(e){console.warn('N7 artwork could not load:',e.name)}}
function setKind(kind){if(!label[kind])return;const text=document.querySelector('.n7-conversation-label');if(text&&text.textContent!==label[kind])text.textContent=label[kind];if(kind==='done'&&state.kind!=='done'){state.winkAt=performance.now();if(state.motion?.readyState>=2&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)state.motion.currentTime=4.7;}state.kind=kind;for(const x of state.mounted){x.setAttribute('aria-label','N7: '+label[kind]);x.title='N7 · '+label[kind]}}
function mount(parent,small){if(!parent||parent.querySelector('.n7-live-presence'))return;
 const box=document.createElement('div');box.className='n7-live-presence'+(small?' n7-live-small':'');box.style.cssText=small?'width:52px;height:52px;flex:0 0 52px;':'width:min(210px,60vw);height:auto;aspect-ratio:1;margin:0 auto 8px;';
 box.style.visibility=state.image?'visible':'hidden';box.setAttribute('role','img');box.setAttribute('aria-label','N7');
 const canvas=document.createElement('canvas');canvas.width=650;canvas.height=650;canvas.style.cssText='width:100%;height:100%;display:block;mix-blend-mode:lighten;background:transparent;filter:none;box-shadow:none';
 box.append(canvas);parent.prepend(box);state.mounted.add(box);
 function draw(now){if(!box.isConnected){state.mounted.delete(box);return;}
 const ctx=canvas.getContext('2d');if(state.image&&state.eyes&&ctx){
 const wave=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.sin(now*.0011)*3;
 const usingMotion=state.motion&&state.motion.readyState>=2;
 ctx.clearRect(0,0,650,650);ctx.save();ctx.translate(0,usingMotion?0:wave);
 ctx.drawImage(usingMotion?state.motion:state.image,0,0,650,650);
 if(!usingMotion){ctx.globalAlpha=state.kind==='think'?.86:1;ctx.drawImage(state.eyes,0,0,650,650);ctx.globalAlpha=1;}
 const t=(now-state.winkAt)/1000;
 if(!usingMotion&&state.kind==='done'&&t>=0&&t<1.05){
 const closure=t<.18?t/.18:t<.65?1:Math.max(0,1-(t-.65)/.25);
 ctx.globalAlpha=closure;ctx.fillStyle='#03131b';ctx.beginPath();ctx.ellipse(382,304,49,18,-.18,0,Math.PI*2);ctx.fill();
 ctx.strokeStyle='#76edff';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(341,306);ctx.quadraticCurveTo(378,317,418,290);ctx.stroke();ctx.globalAlpha=1;
 }ctx.restore();
 }requestAnimationFrame(draw)}
 requestAnimationFrame(draw);
}
function ensureMounted(){
 const messages=document.getElementById('messages');if(!messages)return;
 let row=messages.querySelector(':scope > .n7-conversation-status');
 if(!row){
  const nearBottom=messages.scrollHeight-messages.scrollTop-messages.clientHeight<100;
  row=document.createElement('div');row.className='n7-conversation-status';row.setAttribute('role','status');row.setAttribute('aria-live','polite');
  const text=document.createElement('span');text.className='n7-conversation-label';text.textContent=label[state.kind];row.append(text);messages.append(row);
  mount(row,true);
  if(nearBottom)messages.scrollTop=messages.scrollHeight;
 }
 document.querySelectorAll('.n7-live-presence').forEach(x=>{if(x.parentElement!==row){state.mounted.delete(x);x.remove();}});
 document.querySelectorAll('#messages .welcome .logo').forEach(x=>x.style.display='none');
}

let polling=false;
async function syncTasks(){if(polling)return;polling=true;
try{
 const a=await fetch('/api/tasks',{credentials:'same-origin',cache:'no-store'});
 if(!a.ok)return;const x=await a.json();
 if(!Array.isArray(x.tasks))return;
 let success=false;const latest=new Map();
 for(const t of x.tasks){latest.set(t.id,t.status);
 if(state.previous.has(t.id)&&state.previous.get(t.id)!==t.status&&t.status==='completed')success=true;}
 const hadHistory=state.previous.size>0;state.previous=latest;
 if(success){setKind('done');return;}
 if(x.tasks.some(t=>t.status==='running')){setKind('work');return;}
 if(x.tasks.some(t=>t.status==='queued')){setKind('think');return;}
 if(x.tasks[0]?.status==='failed'){setKind('error');return;}
 if(state.kind==='work'||state.kind==='think')setKind('idle');
}catch(_){/* No user-visible false success after a network error */}
finally{polling=false}}
function init(){
 const style=document.createElement('style');style.id='n7-compose-presence-style';
 style.textContent='#application header .n7-presence,#messages .welcome .n7-presence{display:none!important}.n7-conversation-status{display:flex;align-items:center;align-self:flex-start;gap:8px;flex:0 0 auto;margin:0;padding:0;min-height:40px;background:transparent;box-shadow:none}.n7-conversation-status .n7-live-presence{width:40px!important;height:40px!important;flex:0 0 40px!important;pointer-events:none;background:transparent;filter:none;box-shadow:none}.n7-conversation-label{font-size:14px;color:#8fa4b2;font-weight:400;letter-spacing:0}#chat textarea{min-width:0}';
 document.head.append(style);
 document.addEventListener('n7:presence',e=>setKind(e.detail?.state));
 ensureMounted();
 const observer=new MutationObserver(()=>ensureMounted());
 const messages=document.getElementById('messages');if(messages)observer.observe(messages,{childList:true,subtree:false});
 const form=document.getElementById('chat');
 if(form)form.addEventListener('submit',()=>setKind('think'),{capture:true});
 setInterval(()=>{ensureMounted();syncTasks();},4000);
 syncTasks();
 loadArt();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
